'use strict';

const path = require('node:path');
const { dependencyUpdatesFor } = require('../constants');

// User-facing text keyed by dep name. `hint` follows the dep name in the
// recommendation line; `column` is the display suffix in the file list.
const REMOVAL_COPY = {
  '@sap/cds-compiler': {
    hint: 'we recommend removing this dependency. It is unlikely that you need to call its API directly.',
    column: '@sap/cds-compiler',
  },
  '@sap/cds-dk': {
    hint: 'we recommend removing this dependency (it is a global tool).',
    column: '@sap/cds-dk',
  },
};

async function runRemovals(ctx, cds) {
  const { askYesNo, NonTTYError } = require('../util/prompt');
  const { info, bold, dim } = require('../../../lib/util/term');

  const removals = ctx.proposal?.removals || [];
  if (removals.length === 0) return;

  const dep = dependencyUpdatesFor(ctx.target);
  const bumpRange = name => dep.node?.[name] || `^${ctx.target}`;

  // Group by dep name.
  const byName = new Map();
  for (const r of removals) {
    if (!byName.has(r.name)) byName.set(r.name, []);
    byName.get(r.name).push(r);
  }

  for (const [name, list] of byName) {
    const copy = REMOVAL_COPY[name] || {
      hint: 'we recommend removing this dependency.',
      column: name,
    };
    console.log();
    console.log(`'${name}': ${copy.hint}`);
    console.log();
    for (const r of list) {
      console.log(`  ${bold(path.relative(cds.root, r.file))} > ${copy.column}`);
    }
    console.log();

    let accept;
    try {
      accept = await askYesNo('Remove it?');
    } catch (e) {
      if (e instanceof NonTTYError) return;   // skip silently on non-TTY
      throw e;
    }

    // Apply either removal (accept) or version bump (decline).
    const files = new Set(list.map(r => r.file));
    for (const pkgPath of files) {
      const pkg = JSON.parse(cds.utils.fs.readFileSync(pkgPath, 'utf8'));
      let touched = false;
      let action;
      for (const kind of ['dependencies', 'devDependencies']) {
        const current = pkg[kind]?.[name];
        if (!current) continue;
        if (accept) {
          delete pkg[kind][name];
          action = `removed ${name}`;
          touched = true;
        } else {
          const target = bumpRange(name);
          if (current !== target) {
            pkg[kind][name] = target;
            action = `${name}: ${current} → ${target}`;
            touched = true;
          }
        }
      }
      if (touched) {
        cds.utils.fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n');
        console.log(`  ${info('✓')} ${path.relative(cds.root, pkgPath)}  ${dim(`(${action})`)}`);
        ctx.rewriteRan = true;
      }
    }
  }
}

module.exports = { runRemovals };
